function fewestBumps(target: number[]): number {
  // bumps for target[lo..hi] when every element already has height base
  const solve = (lo: number, hi: number, base: number): number => {
    if (lo > hi) return 0;
    let m = Infinity;
    for (let i = lo; i <= hi; i++) m = Math.min(m, target[i]);
    let total = m - base, start = lo;
    for (let i = lo; i <= hi + 1; i++) {
      if (i === hi + 1 || target[i] === m) {
        total += solve(start, i - 1, m);
        start = i + 1;
      }
    }
    return total;
  };
  return solve(0, target.length - 1, 0);
}

