class Solution:
    def fewestBumps(self, target: List[int]) -> int:
        def solve(lo, hi, base):
            if lo > hi:
                return 0
            m = min(target[lo:hi + 1])
            total, start = m - base, lo
            for i in range(lo, hi + 2):
                if i == hi + 1 or target[i] == m:
                    total += solve(start, i - 1, m)
                    start = i + 1
            return total
        return solve(0, len(target) - 1, 0)

